-- MP-0012: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0012: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('shaharizukirnain-abd-kadir','alias-razak','ahmad-amzad-hashim') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0012: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('setiu','kuala nerus','kuala terengganu') and slug not in ('shaharizukirnain-abd-kadir','alias-razak','ahmad-amzad-hashim')) then raise exception 'MP-0012: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0012:%' and (m.source_type <> 'editorial' or e.slug not in ('shaharizukirnain-abd-kadir','alias-razak','ahmad-amzad-hashim') or m.import_key not like 'MP-0012:' || e.slug || ':%')) then raise exception 'MP-0012: milestone identity conflict'; end if;
end $$;

